const configRows = $('Leer Configuracion').all().map(i => i.json);
const config = {};
for (const row of configRows) {
  config[row.clave] = row.valor;
}

const movimientos = $('Leer Movimientos Validados').all().map(i => i.json).filter(m => m.id);

if (movimientos.length === 0) {
  return [{ json: { error: 'No hay movimientos para procesar' } }];
}

const propiedadId = movimientos[0].propiedad_id;
const tipoGestion = movimientos[0].tipo_gestion_default;

const alquileres = movimientos.filter(m => m.tipo === 'Alquiler');
const suministros = movimientos.filter(m => m.tipo === 'Suministros');
const gastosMovs = movimientos.filter(m => m.tipo && m.tipo.startsWith('Gasto') && !m.tipo.includes('Reparacion'));
const reparacionesMovs = movimientos.filter(m => m.tipo === 'Gasto_Reparacion');
const colaboradoresRepercutibles = $('Leer Colaboradores Repercutibles').all().map(i => i.json).filter(c => c.id);
const gastosColaboradores = colaboradoresRepercutibles.reduce((sum, c) => sum + parseFloat(c.importe_calculado), 0);
const conDescuadre = movimientos.some(m => m.estado_validacion === 'descuadrado' || m.estado_validacion === 'pago_parcial');

const ingresosAlquiler = alquileres.reduce((sum, m) => {
  const importe = m.estado_validacion === 'pago_parcial' ? parseFloat(m.monto_cobrado) : parseFloat(m.monto);
  return sum + importe;
}, 0);
const ingresosSuministros = suministros.reduce((sum, m) => sum + parseFloat(m.monto), 0);
const ingresosTotales = ingresosAlquiler + ingresosSuministros;

const gastos = gastosMovs.reduce((sum, m) => sum + parseFloat(m.monto), 0);

// --- REPARACIONES (regla confirmada por the client: ×1.4 sobre la base; umbral 500€ IVA incluido) ---
const margenReparacion = parseFloat(config['reparaciones_margen_pct']) / 100; // 40 -> 0.4
const umbralReparacion = parseFloat(config['reparaciones_umbral_abono']); // 500
const ivaPct = parseFloat(config['iva']);

let reparacionesDeducidasMes = 0;
let reparacionesFacturaAparte = [];

const reparacionesDeducidasDetalle = [];

for (const r of reparacionesMovs) {
  const base = parseFloat(r.monto);
  const facturado = base * (1 + margenReparacion);
  const facturadoConIva = facturado * (1 + ivaPct);
  if (facturadoConIva > umbralReparacion) {
    reparacionesFacturaAparte.push({ concepto: r.descripcion, base, facturado: Math.round(facturado * 100) / 100, facturado_con_iva: Math.round(facturadoConIva * 100) / 100 });
  } else {
    reparacionesDeducidasMes += facturado;
    reparacionesDeducidasDetalle.push({ concepto: r.descripcion, base, facturado: Math.round(facturado * 100) / 100 });
  }
}

// --- ROTACIONES ---
// Rotación habitaciones (75€ fijo) — nunca supera el umbral, siempre se descuenta
const rotacionesHabitacionMovs = movimientos.filter(m => m.tipo === 'Rotacion_Propietario' || m.tipo === 'Rotacion_Habitacion_Propietario');
const tarifaRotacionPropietario = parseFloat(config['rotacion_habitaciones_propietario']);
const rotacionesHabitacion = rotacionesHabitacionMovs.reduce((sum, m) => {
  const monto = parseFloat(m.monto) || 0;
  return sum + (monto > 0 ? monto : tarifaRotacionPropietario);
}, 0);

// Rotación tradicional (1 mensualidad) — sí puede superar el umbral de 500€ IVA incluido
const rotacionesTradicionalMovs = movimientos.filter(m => m.tipo === 'Rotacion_Tradicional');
let rotacionesTradicionalDeducida = 0;
const rotacionesTradicionalFacturaAparte = [];

for (const r of rotacionesTradicionalMovs) {
  const base = parseFloat(r.monto);
  const conIva = base * (1 + ivaPct);
  if (conIva > umbralReparacion) {
    rotacionesTradicionalFacturaAparte.push({ concepto: r.descripcion, base, con_iva: Math.round(conIva * 100) / 100 });
  } else {
    rotacionesTradicionalDeducida += base;
  }
}

const rotaciones = rotacionesHabitacion + rotacionesTradicionalDeducida;

// --- Comisión de gestión ---
let pctComision = 0;
if (tipoGestion === 'tradicional') pctComision = parseFloat(config['tradicional_pct']);
else if (tipoGestion === 'habitaciones') pctComision = parseFloat(config['habitaciones_pct']);
else if (tipoGestion === 'turistico') pctComision = parseFloat(config['turistico_pct']);

const honorarios = ingresosAlquiler * pctComision;

const baseIva = honorarios + gastos + reparacionesDeducidasMes + rotaciones + gastosColaboradores;
const iva = baseIva * ivaPct;

const netoPropietario = ingresosTotales - gastos - honorarios - iva - rotaciones - reparacionesDeducidasMes - gastosColaboradores;

const cobroDirecto = movimientos[0].cobro_directo_propietario === true || movimientos[0].cobro_directo_propietario === 't';

let netoFinal = netoPropietario;
let estadoFinal = conDescuadre ? 'pendiente' : 'validado';
let notaCobroDirecto = null;

if (cobroDirecto) {
  netoFinal = 0;
  estadoFinal = 'factura_aparte';
  notaCobroDirecto = `Cobro directo al propietario: el inquilino paga el alquiler directamente. Se factura aparte: honorarios ${Math.round(honorarios*100)/100}€ + IVA ${Math.round(honorarios*ivaPct*100)/100}€ = ${Math.round(honorarios*(1+ivaPct)*100)/100}€. No hay transferencia de alquiler.`;
}

if (rotacionesTradicionalFacturaAparte.length > 0 && estadoFinal !== 'factura_aparte') {
  estadoFinal = 'pendiente';
}

return [{
  json: {
    propiedad_id: propiedadId,
    ingresos: Math.round(ingresosTotales * 100) / 100,
    gastos: Math.round(gastos * 100) / 100,
    honorarios_gestion: Math.round(honorarios * 100) / 100,
    iva: Math.round(iva * 100) / 100,
    rotaciones: Math.round(rotaciones * 100) / 100,
    reparaciones: Math.round(reparacionesDeducidasMes * 100) / 100,
    neto_propietario: Math.round(netoFinal * 100) / 100,
    estado: estadoFinal,
    detalle_calculo: JSON.stringify({
      tipo_gestion: tipoGestion,
      pct_comision: pctComision,
      ingresos_alquiler: Math.round(ingresosAlquiler * 100) / 100,
      ingresos_suministros: Math.round(ingresosSuministros * 100) / 100,
      gastos_detalle: gastosMovs.map(g => ({ concepto: g.tipo, monto: g.monto })),
      nota_cobro_directo: notaCobroDirecto,
      reparaciones_deducidas_este_mes: Math.round(reparacionesDeducidasMes * 100) / 100,
      reparaciones_factura_aparte: reparacionesFacturaAparte,
      rotaciones_habitacion_detalle: rotacionesHabitacionMovs.map(r => ({ concepto: r.tipo, monto: r.monto })),
      rotaciones_tradicional_deducida: Math.round(rotacionesTradicionalDeducida * 100) / 100,
      rotaciones_tradicional_factura_aparte: rotacionesTradicionalFacturaAparte,
      reparaciones_detalle: reparacionesDeducidasDetalle,
      nota: conDescuadre
        ? 'Hay movimientos descuadrados incluidos en el cálculo — revisar antes de cerrar'
        : (reparacionesFacturaAparte.length > 0 || rotacionesTradicionalFacturaAparte.length > 0
          ? 'Hay reparaciones o rotaciones que superan el umbral de 500€ (IVA incluido) — se facturan aparte, no se han descontado de esta liquidación'
          : 'Todos los movimientos están validados')
    })
  }
}];

const datos = $('Motor de Reglas').all();
const ultimo = datos[datos.length - 1].json;

return [{
  json: {
    propiedad_id: ultimo.propiedad_id,
    neto_propietario: ultimo.neto_propietario
  }
}];
